mapper.select:
SELECT fd.id, fdd.id as detailId, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.packing_status AS packingStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, op.code as provideCode, fdd.platform_sku_no as thirdWarehouseSku, fd.logistics_status, fd.declare_status FROM first_mile_delivery_detail fdd LEFT JOIN first_mile_delivery fd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = fd.dest_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.id, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.packing_status AS packingStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, op.code as provideCode, fdd.platform_sku_no as thirdWarehouseSku, fd.logistics_status, fd.declare_status FROM first_mile_delivery fd INNER JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = fd.dest_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT DISTINCT fd.id, fd.packing_status, fd.code, CAST(fmcb.box_no AS INTEGER) AS box_no, concat(box_length, '*', fmc.box_width, '*', fmc.box_height) AS boxSize, fmc.package_weight, fmcb.box_desc FROM first_mile_delivery fd LEFT JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id LEFT JOIN wms_carton fmc ON fmc.source_id = fd.id AND fmc.is_deleted = FALSE LEFT JOIN wms_carton_bill fmcb ON fmc.id = fmcb.carton_id AND fmcb.is_deleted = FALSE WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY fd.code, CAST(fmcb.box_no AS INTEGER)

select fmd.source_id as sourceId, fmd.source_code as sourceCode, fmd.source_type as sourceType, fmd.id as outstockId, fmd.code as outstockCode, fmd.shop_id as shopId, fmd.shop_name as shopName, fmd.approve_time as approveTime, fmd.delivery_warehouse_name as fromWarehouseName, fw.address as fromAddress, fmd.dest_warehouse_name as toWarehouseName, fmd.country_name as toCountryName, fmd.country_id as toCountry, tw.address as toAddress, fmd.remark from first_mile_delivery fmd left join warehouse fw on fmd.delivery_warehouse_id = fw.id and fw.is_deleted =false left join warehouse tw on fmd.dest_warehouse_id = tw.id and tw.is_deleted = false where fmd.is_deleted = false
AND fmd.packing_status = #{params.packingStatus}
AND fmd.logistics_status = #{params.logisticsStatus}
AND fmd.id IN
#{id}

SELECT  EXTRACT(year FROM md.approve_time),  EXTRACT(month FROM md.approve_time) as month,
        count(1)
from first_mile_delivery md
where md.is_deleted = false
  and md.declare_status != 'none'

    and  md.approve_status = #{status}


    and md.approve_time >= #{beginDate}


    and md.approve_time <=  #{endDate}



    ${permissionSql}

group by EXTRACT(month FROM md.approve_time), EXTRACT(year FROM md.approve_time)
order by  EXTRACT(year FROM md.approve_time), EXTRACT(month FROM md.approve_time)

select fmd.id as sourceId, fmd.code as sourceCode, fmd.country_id as country, fmd.country_name as countryName, fmd.source_type as businessType from first_mile_delivery fmd where fmd.is_deleted = false
AND fmd.packing_status = #{params.packingStatus}
AND fmd.declare_status = #{params.declareStatus}
AND fmd.id IN
#{id}
